void QrtiDDShandler::setUp_rtiDDS_handler()
{
    rtiDDSlistener = new QrtiDDSlistener(this);
    rtiDDS = new QrtiDDS(this, rtiDDSlistener);
    connect(rtiDDSlistener, SIGNAL(newData(QString)),
            this, SLOT(readListenerData(QString)),
            Qt::QueuedConnection);
}
